def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    if len(sys.argv)!=2: raise SystemExit("Usage: apply.py <exact-territory-1.4.0-source>")
    root=Path(sys.argv[1]).resolve(strict=True); here=Path(__file__).resolve().parent
    for rel,expected in BASE.items(): assert sha(root/rel)==expected,f"Unexpected 1.4.0 base: {rel}"
    encoded=[]
    for name,expected in CHUNKS:
        raw=(here/'chunks'/name).read_text().strip(); assert hashlib.sha256(raw.encode()).hexdigest()==expected,f"Patch segment {name} changed"; encoded.append(raw)
    patch=zlib.decompress(base64.b64decode(''.join(encoded))); assert hashlib.sha256(patch).hexdigest()==PATCH_SHA
    with tempfile.NamedTemporaryFile(prefix='tcs150-',suffix='.patch',delete=False) as f: f.write(patch); name=f.name
    try:
        subprocess.run(['git','apply','--check','--directory='+root.name,name],cwd=root.parent,check=True)
        subprocess.run(['git','apply','--directory='+root.name,name],cwd=root.parent,check=True)
    finally: Path(name).unlink(missing_ok=True)
    for rel,expected in FIXED.items(): assert sha(root/rel)==expected,f"1.5.0 output mismatch: {rel}"
